const UniformVisionLayout = () => {
  return (
    <main className="min-h-screen w-full overflow-x-hidden bg-white">
      {/* Same Vision header */}
      <Navbar />

      {/* Same Vision spacing below navbar */}
      <div className="pt-32" aria-hidden="true" />

      {/* Same Vision alignment/container */}
      <article className="mx-auto flex w-full flex-col items-start lg:w-[90%] lg:max-w-6xl lg:pl-[22px] px-4 sm:px-6 md:px-8 lg:pr-0">
        {/* All 10 supplied SVGs — unchanged */}
        {[svg1, svg2, svg3, svg4, svg5, svg6, svg7, svg8, svg9, svg10].map((svg, index) => (
          <section
            key={index}
            className="relative z-10 w-full max-w-[1000px] overflow-hidden"
          >
            <div
              className="block w-full leading-none [&>svg]:block [&>svg]:h-auto [&>svg]:w-full"
              dangerouslySetInnerHTML={{ __html: svg }}
            />
          </section>
        ))}
      </article>

      {/* Same bottom breathing room as Vision */}
      <div className="pt-32" aria-hidden="true" />

      {/* Same Vision footer */}
      <Footer />
    </main>
  );
};

export default UniformVisionLayout;
